// The live vocal detector's weights (DECISIONS §123; tools/truth/voxtrain.py wrote this file — do not edit by hand).
// A 40 x 34 log-mel window -> conv 3x3 x16 -> pool 2 -> conv 3x3 x16 -> pool 2 -> dense 32 -> dense 1 -> sigmoid, 38385 parameters,
// Float16 little-endian, base64 (76770 bytes), in the order conv1.weight, conv1.bias, conv2.weight, conv2.bias, fc1.weight, fc1.bias, fc2.weight, fc2.bias; ears/vox-net.js decodes and runs it as a stream.
// Trained 2026-10-12 on CPU: the Jamendo singing-voice corpus (Ramona, Richard, David, ICASSP 2008; Zenodo record 2585988, CC BY 4.0 — the audio
// is not here, these weights are the derived work and this line is its attribution; THIRD-PARTY.md has the full notice) train + valid,
// 61 + 16 tracks, plus six library tracks' ear-accepted hand windows (§122); 12 epochs x 400000 windows of 40 x 34, batch 512, Adam 1e-3 cosine, BCE (pos_weight 1.0), gain / tilt / level / noise jitter; the six training tracks' Demucs accompaniments as negatives and eight cross-track remixes of their vocal stems (labelled by the stem's level); the best Jamendo-valid AUC epoch kept (6).
// Jamendo test F1 0.792 / AUC 0.875; the held-out library pair IBelongHere F1 0.819 / AUC 0.838, Comptine false positives 11.6 %.
export const VOX_W = {
  nMel: 40, tWin: 34, nParams: 38385,
  shapes: {'conv1.weight': [16, 1, 3, 3], 'conv1.bias': [16], 'conv2.weight': [16, 16, 3, 3], 'conv2.bias': [16], 'fc1.weight': [32, 1120], 'fc1.bias': [32], 'fc2.weight': [1, 32], 'fc2.bias': [1]},
  order: ['conv1.weight', 'conv1.bias', 'conv2.weight', 'conv2.bias', 'fc1.weight', 'fc1.bias', 'fc2.weight', 'fc2.bias'],
  f16: '',
};
